llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "In healthy volunteers, pethidine had an absolute bioavailability of 0.61 versus IV, well above the 20% threshold."
    },
    {
      "card_ids": ["C31"],
      "claim": "In humans, maraviroc 100 mg tablet had an absolute bioavailability of 23.1% (95% CI 19.2-27.8) versus IV, above the 20% threshold."
    },
    {
      "card_ids": ["C47"],
      "claim": "In young healthy subjects, perindoprilat after oral perindopril had a bioavailability of 19% ± 7%, below the 20% threshold; this is the only molecule-level negative result."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C47"],
  "decision_summary": "Nine of ten high-transfer evidence molecules have numeric absolute oral bioavailability values at or above 20%, mostly 23-95%, while one molecule is just below threshold at 19%; the preponderance of direct, ordinary-condition evidence supports high bioavailability.",
  "evidence_gaps": [
    "One evidence molecule had F=19%, just below the 20% threshold, introducing minor uncertainty.",
    "Some records are qualitative or from special populations, but the decision relies on numeric ordinary-condition measurements."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C15", "C31"],
  "revision_action": "initial",
  "supportive_card_ids": ["C15", "C31"]
}

